exercises.reference:
import ast
import operator

_BINARY = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul,
           ast.Div: operator.truediv, ast.Pow: operator.pow}
_UNARY = {ast.UAdd: operator.pos, ast.USub: operator.neg}
MAX_EXPONENT = 1000

def safe_eval(text):
    try:
        tree = ast.parse(text, mode="eval")
    except SyntaxError as err:
        raise ValueError(f"not an expression: {err.msg}") from None
    return _eval(tree.body)

def _eval(node):
    if isinstance(node, ast.Constant):
        if type(node.value) in (int, float):        # excludes bool, str, None, ...
            return node.value
        raise ValueError(f"unsupported literal: {node.value!r}")
    if isinstance(node, ast.UnaryOp) and type(node.op) in _UNARY:
        return _UNARY[type(node.op)](_eval(node.operand))
    if isinstance(node, ast.BinOp) and type(node.op) in _BINARY:
        left, right = _eval(node.left), _eval(node.right)
        if isinstance(node.op, ast.Pow) and abs(right) > MAX_EXPONENT:
            raise ValueError("exponent too large")
        return _BINARY[type(node.op)](left, right)
    raise ValueError(f"unsupported syntax: {type(node).__name__}")

exercises.solution:
```python
_BINARY = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul,
           ast.Div: operator.truediv, ast.Pow: operator.pow}
_UNARY = {ast.UAdd: operator.pos, ast.USub: operator.neg}

def _eval(node):
    if isinstance(node, ast.Constant):
        if type(node.value) in (int, float):
            return node.value
        raise ValueError(f"unsupported literal: {node.value!r}")
    if isinstance(node, ast.UnaryOp) and type(node.op) in _UNARY:
        return _UNARY[type(node.op)](_eval(node.operand))
    if isinstance(node, ast.BinOp) and type(node.op) in _BINARY:
        left, right = _eval(node.left), _eval(node.right)
        if isinstance(node.op, ast.Pow) and abs(right) > 1000:
            raise ValueError("exponent too large")
        return _BINARY[type(node.op)](left, right)
    raise ValueError(f"unsupported syntax: {type(node).__name__}")
```

This is a tree-walking interpreter for a tiny subset of Python, and its safety comes from its structure: it is an **allow-list**. Every node type not explicitly handled — `Name`, `Call`, `Attribute`, `Lambda`, `IfExp`, `List`, `FloorDiv` — falls through to `ValueError`, so a future Python version that adds new syntax is rejected by default. Two subtler points: `bool` is a subclass of `int`, so `type(...) in (int, float)` rather than `isinstance` keeps `True` out; and `9 ** 9 ** 9` is right-associative, so the inner `9 ** 9 = 387420489` is computed first and then rejected as an exponent before Python tries to build a number with hundreds of millions of digits. A production version would also bound the size of intermediate results and the depth of nesting.
